CREATE TABLE "RiskAssessment" ("id" TEXT NOT NULL,"ventureId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"scope" TEXT NOT NULL DEFAULT 'enterprise',"status" TEXT NOT NULL DEFAULT 'active',"dimensions" JSONB NOT NULL,"summary" JSONB NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"version" TEXT NOT NULL DEFAULT 'RISK_V1',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RiskAssessment_pkey" PRIMARY KEY ("id"),CONSTRAINT "RiskAssessment_ventureId_fkey" FOREIGN KEY ("ventureId") REFERENCES "Venture"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "RiskAssessment_ventureId_createdAt_idx" ON "RiskAssessment"("ventureId","createdAt"); CREATE INDEX "RiskAssessment_ownerId_idx" ON "RiskAssessment"("ownerId"); CREATE INDEX "RiskAssessment_status_idx" ON "RiskAssessment"("status");
CREATE TABLE "RiskSignal" ("id" TEXT NOT NULL,"assessmentId" TEXT NOT NULL,"dimension" TEXT NOT NULL,"signal" TEXT NOT NULL,"evidence" TEXT NOT NULL,"exposure" DOUBLE PRECISION NOT NULL,"probability" DOUBLE PRECISION NOT NULL,"impact" DOUBLE PRECISION NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"action" TEXT,"ownerLabel" TEXT,"targetMetric" TEXT,"currentValue" DOUBLE PRECISION,"targetValue" DOUBLE PRECISION,"status" TEXT NOT NULL DEFAULT 'open',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RiskSignal_pkey" PRIMARY KEY ("id"),CONSTRAINT "RiskSignal_assessmentId_fkey" FOREIGN KEY ("assessmentId") REFERENCES "RiskAssessment"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "RiskSignal_assessmentId_dimension_idx" ON "RiskSignal"("assessmentId","dimension"); CREATE INDEX "RiskSignal_status_idx" ON "RiskSignal"("status");
CREATE TABLE "ResilienceSnapshot" ("id" TEXT NOT NULL,"ventureId" TEXT NOT NULL,"score" DOUBLE PRECISION NOT NULL,"components" JSONB NOT NULL,"evidence" JSONB NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ResilienceSnapshot_pkey" PRIMARY KEY ("id"),CONSTRAINT "ResilienceSnapshot_ventureId_fkey" FOREIGN KEY ("ventureId") REFERENCES "Venture"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ResilienceSnapshot_ventureId_capturedAt_idx" ON "ResilienceSnapshot"("ventureId","capturedAt");
CREATE TABLE "PortfolioRiskSnapshot" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"enterpriseCount" INTEGER NOT NULL,"criticalSignals" INTEGER NOT NULL,"interventions" INTEGER NOT NULL,"mitigated" INTEGER NOT NULL,"distribution" JSONB NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PortfolioRiskSnapshot_pkey" PRIMARY KEY ("id"),CONSTRAINT "PortfolioRiskSnapshot_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "PortfolioRiskSnapshot_organizationId_capturedAt_idx" ON "PortfolioRiskSnapshot"("organizationId","capturedAt");
CREATE TABLE "FinancialDiscovery" ("id" TEXT NOT NULL,"ventureId" TEXT,"ownerId" TEXT NOT NULL,"household" JSONB NOT NULL,"income" JSONB NOT NULL,"expenses" JSONB NOT NULL,"assets" JSONB NOT NULL,"liabilities" JSONB NOT NULL,"dependents" JSONB NOT NULL,"protections" JSONB NOT NULL,"goals" JSONB NOT NULL,"horizonMonths" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FinancialDiscovery_pkey" PRIMARY KEY ("id"),CONSTRAINT "FinancialDiscovery_ventureId_fkey" FOREIGN KEY ("ventureId") REFERENCES "Venture"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "FinancialDiscovery_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "FinancialDiscovery_ownerId_createdAt_idx" ON "FinancialDiscovery"("ownerId","createdAt"); CREATE INDEX "FinancialDiscovery_ventureId_idx" ON "FinancialDiscovery"("ventureId");
CREATE TABLE "ProtectionGap" ("id" TEXT NOT NULL,"discoveryId" TEXT NOT NULL,"category" TEXT NOT NULL,"needAmount" DOUBLE PRECISION,"protectedAmount" DOUBLE PRECISION,"gapAmount" DOUBLE PRECISION,"severity" TEXT NOT NULL,"evidence" TEXT NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"status" TEXT NOT NULL DEFAULT 'open',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProtectionGap_pkey" PRIMARY KEY ("id"),CONSTRAINT "ProtectionGap_discoveryId_fkey" FOREIGN KEY ("discoveryId") REFERENCES "FinancialDiscovery"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ProtectionGap_discoveryId_category_idx" ON "ProtectionGap"("discoveryId","category"); CREATE INDEX "ProtectionGap_status_idx" ON "ProtectionGap"("status");
CREATE TABLE "FinancialProtectionScenario" ("id" TEXT NOT NULL,"discoveryId" TEXT NOT NULL,"name" TEXT NOT NULL,"assumptions" JSONB NOT NULL,"result" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FinancialProtectionScenario_pkey" PRIMARY KEY ("id"),CONSTRAINT "FinancialProtectionScenario_discoveryId_fkey" FOREIGN KEY ("discoveryId") REFERENCES "FinancialDiscovery"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "FinancialProtectionScenario_discoveryId_createdAt_idx" ON "FinancialProtectionScenario"("discoveryId","createdAt");
CREATE TABLE "FinancialAction" ("id" TEXT NOT NULL,"discoveryId" TEXT NOT NULL,"objective" TEXT NOT NULL,"gap" TEXT NOT NULL,"alternatives" JSONB NOT NULL,"assumptions" JSONB NOT NULL,"expectedImpact" TEXT NOT NULL,"priority" INTEGER NOT NULL,"decision" TEXT,"status" TEXT NOT NULL DEFAULT 'proposed',"reviewAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FinancialAction_pkey" PRIMARY KEY ("id"),CONSTRAINT "FinancialAction_discoveryId_fkey" FOREIGN KEY ("discoveryId") REFERENCES "FinancialDiscovery"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "FinancialAction_discoveryId_status_idx" ON "FinancialAction"("discoveryId","status"); CREATE INDEX "FinancialAction_priority_idx" ON "FinancialAction"("priority");
CREATE TABLE "DataConsent" ("id" TEXT NOT NULL,"organizationId" TEXT,"grantorUserId" TEXT NOT NULL,"granteeUserId" TEXT,"domain" TEXT NOT NULL,"scopes" TEXT[],"purpose" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'active',"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DataConsent_pkey" PRIMARY KEY ("id"),CONSTRAINT "DataConsent_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "DataConsent_grantorUserId_fkey" FOREIGN KEY ("grantorUserId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "DataConsent_granteeUserId_fkey" FOREIGN KEY ("granteeUserId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "DataConsent_grantorUserId_domain_status_idx" ON "DataConsent"("grantorUserId","domain","status"); CREATE INDEX "DataConsent_organizationId_domain_status_idx" ON "DataConsent"("organizationId","domain","status");
